import { useState } from "react";
import { AED_SOURCE_CATALOG } from "../../sources/catalog";
import type { ImportRun, StoredSource } from "../../services/staging";
import { SourceInstallationAction } from "./SourceInstallationAction";

export function SourceInventory({ sources, runs, removed, canManage, busy, collect, change, requestAdmin }: {
  sources: StoredSource[]; runs: ImportRun[]; removed: string[]; canManage: boolean; busy: boolean;
  collect: (id: string) => Promise<void>; change: (id: string, installed: boolean) => Promise<void>;
  requestAdmin: () => void;
}) {
  const [available, setAvailable] = useState(false);
  const profiles = AED_SOURCE_CATALOG.map((p) => ({ id: p.id, name: p.name, subtitle: p.referenceScope.geographyLabel, url: p.catalogUrl, type: p.formatLabel, connector: true, locked: p.collection.requiresToken }));
  const files = sources.filter((s) => !profiles.some((p) => p.id === s.id))
    .map((s) => ({ id: s.id, name: s.name, subtitle: s.referenceScope?.geographyLabel ?? s.upstreamOrigin, url: s.url, type: s.synthetic ? "Dane demonstracyjne" : "Import plikowy", connector: false, locked: false }));
  const all = [...profiles, ...files];
  const installed = all.filter((s) => !removed.includes(s.id));
  const items = available ? all.filter((s) => removed.includes(s.id)) : installed;
  return <>
    <div className="inventory-filter" role="group" aria-label="Stan instalacji">
      <button type="button" aria-pressed={!available} onClick={() => setAvailable(false)}>Zainstalowane źródła ({installed.length})</button>
      <button type="button" aria-pressed={available} onClick={() => setAvailable(true)}>Do zainstalowania ({all.length - installed.length})</button>
    </div>
    <div className="inventory-grid">{items.map((item) => {
      const run = runs.find((r) => r.sourceId === item.id);
      return <article key={item.id} className="inventory-card">
        <span className="inventory-format">{item.type}</span><h3>{item.name}</h3><p>{item.subtitle}</p>
        <small>{run ? `Ostatni import: ${new Date(run.fetchedAt).toLocaleString("pl-PL")} · ${run.importedCount} wpisów` : "Brak importów z tego źródła"}</small>
        <a href={item.url} target="_blank" rel="noreferrer">Publikacja źródłowa ↗</a>
        <div className="inventory-actions">
          {item.connector && !available && <button className="button button-primary" disabled={busy} onClick={() => void collect(item.id)}>{item.locked ? "Pobierz (wymaga tokenu)" : "Pobierz dane"}</button>}
          <SourceInstallationAction id={item.id} name={item.name} installed={!available} busy={busy} canManage={canManage} requestAdmin={requestAdmin} change={change} />
        </div>
      </article>;
    })}</div>
    {!items.length && <p className="empty-state compact">{available ? "Wszystkie dostępne źródła są zainstalowane." : "Brak zainstalowanych źródeł."}</p>}
  </>;
}
